import{bQ as s,aL as i,u as e,G as n}from"./chunks/framework.C1gZXFVa.js";const u=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md"}'),t={name:"guide/quick-start.md"};function l(o,a,h,p,r,c){return i(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><blockquote><p><strong>一句话路线</strong>：先查服务器的系统、架构、Python 版本 → 按表选离线包 → 拷到服务器上运行 <code>install.sh</code> → 看到 <code>&quot;ping&quot;: &quot;pong&quot;</code> 就是装好了。</p></blockquote><h2 id="开始之前-先确认你的服务器信息" tabindex="-1">开始之前：先确认你的服务器信息 <a class="header-anchor" href="#开始之前-先确认你的服务器信息" aria-label="Permalink to &quot;开始之前：先确认你的服务器信息&quot;">​</a></h2><blockquote><p>在你的服务器上运行下面三条命令，记下结果，选包的时候要用：</p></blockquote><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/os-release</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 看系统：Rocky Linux 9 / Ubuntu 24.04 / Debian 12 等</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uname</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # 看 CPU 架构：显示 x86_64 或 aarch64（aarch64 就是 ARM64）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 看 Python 版本：需要 3.11 或以上</span></span></code></pre></div><ul><li><strong>系统</strong>在支持范围内：EL 9 系列 / Ubuntu 24.04 / Ubuntu 22.04 / Debian 12（对照<a href="/guide/platforms">平台支持矩阵</a>）</li><li><strong>架构</strong>是 <code>x86_64</code> 或 <code>aarch64</code> 之一</li><li><strong>Python</strong> 版本 &gt;= 3.11</li></ul><blockquote><p>💡 <strong>不需要 root</strong>：普通用户也可以安装（装到你的家目录里）；用 root 安装则全机器可用。</p></blockquote><blockquote><p>另外，被管理的那些机器（目标节点）不需要任何准备，它们只要有 SSH 和任意版本的 Python 就行——这是 Ansible 本身的规矩，和本项目无关。</p></blockquote><h2 id="三步安装-新手路线" tabindex="-1">三步安装（新手路线） <a class="header-anchor" href="#三步安装-新手路线" aria-label="Permalink to &quot;三步安装（新手路线）&quot;">​</a></h2><h3 id="第一步-下载适合你机器的离线包" tabindex="-1">第一步：下载适合你机器的离线包 <a class="header-anchor" href="#第一步-下载适合你机器的离线包" aria-label="Permalink to &quot;第一步：下载适合你机器的离线包&quot;">​</a></h3><ul><li>到<a href="/guide/download">下载与校验</a>页按你的系统、架构对照表选包并下载，国内网络可以从 Gitee 镜像下载，通常更快。</li></ul><h3 id="第二步-把包拷到内网服务器并解压" tabindex="-1">第二步：把包拷到内网服务器并解压 <a class="header-anchor" href="#第二步-把包拷到内网服务器并解压" aria-label="Permalink to &quot;第二步：把包拷到内网服务器并解压&quot;">​</a></h3><ul><li>用 U 盘、跳板机或内网文件服务器把 <code>.tar.gz</code> 文件拷到服务器上，然后解压：</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ansible-offline-install-2.0.0-el9-aarch64-py311.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ansible-offline-install-2.0.0-bundle</span></span></code></pre></div><h3 id="第三步-运行安装-并确认成功" tabindex="-1">第三步：运行安装，并确认成功 <a class="header-anchor" href="#第三步-运行安装-并确认成功" aria-label="Permalink to &quot;第三步：运行安装，并确认成功&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span></code></pre></div><ul><li>脚本会用中文逐行打印进度，最后自动做一次验证。看到类似下面的输出，出现 <code>&quot;ping&quot;: &quot;pong&quot;</code> 就说明装好了：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ansible-offline] 正在验证安装</span></span>
<span class="line"><span>localhost | SUCCESS =&gt; {</span></span>
<span class="line"><span>    &quot;changed&quot;: false,</span></span>
<span class="line"><span>    &quot;ping&quot;: &quot;pong&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>[ansible-offline] 完成。Ansible 已就绪，全程离线。</span></span></code></pre></div><blockquote><p>✅ 再试一下 <code>ansible --version</code>，能打印版本号，就可以开始写你的第一个 playbook 了。</p></blockquote><ul><li>装不上先看<a href="/guide/faq">常见问题</a>；想换 Ansible 版本或增减随包的 collections，见<a href="/guide/build">自制离线包</a>。</li></ul><h2 id="名词解释" tabindex="-1">名词解释 <a class="header-anchor" href="#名词解释" aria-label="Permalink to &quot;名词解释&quot;">​</a></h2><ul><li><strong>离线包</strong>：把安装需要的全部文件提前打包好的一个压缩文件，拿到没网的机器上也能安装。</li><li><strong>wheel</strong>：Python 的预制安装包格式，好比 Windows 里的安装程序，装的时候不用现场编译，快且稳。</li><li><strong>venv（虚拟环境）</strong>：一个独立的文件夹，专门放这一套 Ansible，和系统环境互不干扰，删除文件夹即彻底卸载。</li><li><strong>collection</strong>：Ansible 的插件包，用来扩展功能，比如管理防火墙、云厂商的模块。本项目默认附带 <code>ansible.posix</code> 和 <code>community.general</code> 两个最常用的。</li></ul>`,22)])])}const k=s(t,[["render",l]]);export{u as __pageData,k as default};
